describe('Form Data Persistence on Navigation', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should persist form data when user navigates away and returns', () => {
    // Fill form with valid data
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');

    // Verify data is present before navigation
    cy.get('[data-testid="name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'john@example.com');

    // Navigate away from the page
    cy.get('[data-testid="nav-link"]').click();
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Navigate back to the form page
    cy.get('[data-testid="nav-back-link"]').click();

    // Verify form data is still persisted
    cy.get('[data-testid="name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'john@example.com');
    cy.get('[data-testid="message-textarea"]').should('have.value', 'This is a test message');

    // Verify form is still in a valid state
    cy.get('[data-testid="submit-button"]').should('be.visible');
  });

  it('should clear form data when user navigates away and returns without saving', () => {
    // Fill form with data
    cy.get('[data-testid="name-input"]').type('Jane Smith');
    cy.get('[data-testid="email-input"]').type('jane@example.com');

    // Navigate away from the page
    cy.get('[data-testid="nav-link"]').click();
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Navigate back to the form page
    cy.get('[data-testid="nav-back-link"]').click();

    // Verify form data is NOT persisted (or is cleared)
    cy.get('[data-testid="name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');

    // Verify form is empty and ready for new input
    cy.get('[data-testid="name-input"]').should('be.empty');
    cy.get('[data-testid="email-input"]').should('be.empty');
  });
});
